INSERT INTO sections (source_document, chapter_number, chapter_title, section_code, title, purpose, purpose_thanglish, summary, business_meaning, business_explanation, business_explanation_thanglish, raw_text, pages, keywords, intent, tags) VALUES ('HBP Chapter 2.pdf', '2', 'General Provisions Regarding Imports and Exports', '2.41', 'Other Conditions for Import of Replacement Goods', '2.41 Other Conditions for Import of Replacement Goods
